import{_ as t,o,c as a,ai as n}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Language Compare — Understanding the Token Tax","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/language-compare.md","filePath":"en/guide/language-compare.md"}'),s={name:"en/guide/language-compare.md"};function r(i,e,l,h,u,g){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="language-compare-—-understanding-the-token-tax" tabindex="-1">Language Compare — Understanding the Token Tax <a class="header-anchor" href="#language-compare-—-understanding-the-token-tax" aria-label="Permalink to &quot;Language Compare — Understanding the Token Tax&quot;">​</a></h1><p>The Language Compare preset reveals how the same meaning costs different amounts of tokens depending on the language you write it in. This is not a bug — it is a fundamental property of how LLMs process text.</p><p><strong>Parent page:</strong> <a href="./compare.html">Compare</a><strong>Route:</strong> <code>/compare</code> (Language Compare preset)</p><h2 id="what-is-language-compare" tabindex="-1">What is Language Compare? <a class="header-anchor" href="#what-is-language-compare" aria-label="Permalink to &quot;What is Language Compare?&quot;">​</a></h2><p>Language Compare is a preset on the <a href="./compare.html">Compare</a> page. Instead of comparing models or temperatures, it compares <strong>languages</strong>. You provide the same prompt in multiple languages and see how the tokenizer treats each one.</p><p>This exposes <strong>tokenization bias</strong> — the fact that some languages are far more expensive to process than others, even when they express exactly the same idea.</p><h2 id="the-mental-model" tabindex="-1">The Mental Model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The Mental Model&quot;">​</a></h2><p>LLMs do not understand languages. They process <strong>tokens</strong>.</p><p>Before your text reaches the model, a <strong>tokenizer</strong> (typically BPE — Byte Pair Encoding) splits it into tokens. The tokenizer learns its merge rules from the training data. Here is the critical chain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your Text  --&gt;  Tokenizer  --&gt;  Tokens  --&gt;  Model  --&gt;  Response</span></span>
<span class="line"><span>   &quot;Hello&quot;        BPE         [15339]      Inference     &quot;Hi there&quot;</span></span>
<span class="line"><span>   &quot;مرحبا&quot;        BPE       [2318,112,...]  Inference     &quot;...&quot;</span></span></code></pre></div><p>English dominates LLM training corpora. As a result, the tokenizer learns very efficient merges for English words — common words often become a single token. Languages that appear less frequently in training data (Arabic, Hindi, Chinese, Thai, and many others) get <strong>fragmented</strong> into more tokens for the same meaning.</p><p><strong>More tokens means:</strong></p><ul><li><strong>Less context window</strong> — A 4096-token window holds fewer words in Arabic than in English</li><li><strong>Slower generation</strong> — More tokens to produce for an equivalent response</li><li><strong>Higher cost</strong> — On pay-per-token APIs, the same sentence costs more in some languages</li><li><strong>Degraded quality</strong> — The model has less room to reason when context is consumed by inefficient encoding</li></ul><p>This is not a deficiency in any language. It is a statistical consequence of the training data distribution. A tokenizer trained primarily on Arabic text would show the reverse bias.</p><h2 id="how-to-use-it" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h2><ol><li><strong>Open the Compare page</strong> and click the <strong>Language Compare</strong> preset button.</li><li><strong>Three slots appear</strong>, each with a language dropdown. The defaults are English, French, and Arabic — you can change these to any language.</li><li><strong>Type or paste your prompt</strong> into each slot&#39;s textarea. Write the same meaning in each language.</li><li><strong>Automatic language detection</strong> — The system detects which language you actually typed. If it does not match the slot&#39;s selected language, a <strong>&quot;Translate to X&quot;</strong> button appears so you can fix it with one click.</li><li><strong>Click Compare</strong> — All slots run simultaneously and results appear side by side with Token Tax metrics.</li></ol><p>You always own your prompt. Nothing is modified or sent without your action.</p><h2 id="understanding-the-results" tabindex="-1">Understanding the Results <a class="header-anchor" href="#understanding-the-results" aria-label="Permalink to &quot;Understanding the Results&quot;">​</a></h2><p>After the comparison runs, each slot displays several metrics:</p><table tabindex="0"><thead><tr><th>Metric</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Prompt Tokens</strong></td><td>How many tokens the tokenizer produced from your input text</td></tr><tr><td><strong>Token Tax</strong></td><td>The ratio compared to the most efficient language in the comparison (usually English). A tax of 2.3x means the prompt costs 2.3 times as many tokens.</td></tr><tr><td><strong>TTFT</strong></td><td>Time to first token. May be higher for languages that produce more prompt tokens, since the model must process all of them before generating.</td></tr><tr><td><strong>Speed</strong></td><td>Tokens per second during generation. This is usually similar across languages because the model generates tokens at roughly the same rate regardless of language.</td></tr><tr><td><strong>Total Tokens</strong></td><td>The length of the model&#39;s response. The model may produce different length responses in different languages.</td></tr></tbody></table><p>The <strong>Token Tax</strong> is the headline number. It tells you exactly how much more expensive a language is to process, token for token, compared to the baseline.</p><h2 id="translation-feature" tabindex="-1">Translation Feature <a class="header-anchor" href="#translation-feature" aria-label="Permalink to &quot;Translation Feature&quot;">​</a></h2><p>Each slot includes a translation capability powered by your local Ollama model — no cloud service, no cost.</p><ul><li><strong>Quality depends on model size.</strong> Larger models (7B parameters and above) produce significantly better translations than small ones (3B). If translation quality matters, use the best model you have available.</li><li><strong>Thinking models show their work.</strong> If you use a reasoning model like DeepSeek-R1, you will see the <code>&lt;think&gt;</code> block as the model works through the translation.</li><li><strong>You can edit the result.</strong> After translation, the text appears in the slot&#39;s textarea and you can modify it before running the comparison. The translation is a starting point, not a final answer.</li><li><strong>A &quot;Translated&quot; badge</strong> appears on the slot only after machine translation has been used, so you always know which texts were human-written and which were machine-translated.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Use the same model for all slots</strong> to isolate language as the only variable. If you use different models, you cannot tell whether differences come from the language or the model.</li><li><strong>Try different model sizes</strong> with the same prompt to see if the token tax ratio changes. Larger models sometimes have larger vocabularies with better multilingual coverage.</li><li><strong>Connect this to the Educators Kit.</strong> <a href="./../community/educators/module-9.html">Module 9: What Words Cost</a> provides a structured lesson plan built around this exact feature, with exercises and discussion questions for classroom use.</li><li><strong>Short prompts amplify the effect.</strong> A single sentence can show dramatic token count differences. Try a common phrase like &quot;The weather is nice today&quot; in five languages.</li><li><strong>Check both directions.</strong> If your native language is not English, try prompting in your language first — you may find that the model&#39;s response quality differs, not just the token count.</li></ul><h2 id="saving-results" tabindex="-1">Saving Results <a class="header-anchor" href="#saving-results" aria-label="Permalink to &quot;Saving Results&quot;">​</a></h2><p>Comparison runs are automatically saved to your browser&#39;s IndexedDB. No manual action is needed — every completed comparison is preserved locally.</p><ul><li>Saved comparisons appear in the <strong>&quot;Saved Comparisons&quot;</strong> panel on the Compare page.</li><li>Click <strong>&quot;Load&quot;</strong> to reload a past comparison with full results.</li><li>Click <strong>&quot;Delete&quot;</strong> to remove a saved run.</li><li>Data stays local on your machine — nothing is sent to any server.</li></ul><h2 id="exporting-data" tabindex="-1">Exporting Data <a class="header-anchor" href="#exporting-data" aria-label="Permalink to &quot;Exporting Data&quot;">​</a></h2><p>Click the <strong>&quot;Export&quot;</strong> button in the results header to access export options:</p><ul><li><strong>Download as JSON</strong> — Full comparison data including prompts, outputs, metrics, and token counts. Ideal for further analysis in scripts or notebooks.</li><li><strong>Download as Markdown</strong> — Formatted report with tables showing prompts, results, and Token Tax ratios. Ready to paste into documents or blog posts.</li></ul><h2 id="sharing-to-github-discussions" tabindex="-1">Sharing to GitHub Discussions <a class="header-anchor" href="#sharing-to-github-discussions" aria-label="Permalink to &quot;Sharing to GitHub Discussions&quot;">​</a></h2><p>Click <strong>&quot;Share to GitHub Discussions&quot;</strong> in the Export menu to share your findings with the community.</p><ol><li>A dialog opens with a preview of the markdown report.</li><li>Add your own commentary at the top — describe what you discovered.</li><li>Click <strong>&quot;Open GitHub Discussions&quot;</strong> to be redirected to GitHub with the report pre-filled.</li><li>You review and submit the post yourself — nothing is posted without your consent.</li></ol><p>Alternatively, click <strong>&quot;Copy Markdown&quot;</strong> to paste the report anywhere you like.</p><blockquote><p><strong>Your data stays local.</strong> LLMxRay never sends comparison results anywhere automatically. Sharing is always opt-in — you control what gets posted and where.</p></blockquote>`,37)])])}const c=t(s,[["render",r]]);export{p as __pageData,c as default};
